import React, { useState, useEffect } from "react";
import { Link } from 'react-router-dom';


function Subscription() {
    const [subscription, setSubscription] = useState([]);

    useEffect(() => {
        const fetchSubscriptionDetails = async () => {
            try {
                const response = await fetch('http://localhost:8083/subscription-types');
                const data = await response.json();
                setSubscription(data);
                console.log(data); // Используем данные напрямую
            } catch (error) {
                console.error('Error fetching subscription details:', error);
            }
        };

        fetchSubscriptionDetails();
    }, []);


    return (
        <div className="Subscription">
            <h1>Выберите План!</h1>
            <div className="Sub-plans">
                <div className="Sub-plan">
                    <h2>GOLD</h2>
                    <h3>План на 1 месяц</h3>
                    <h3>500 ТОКЕНОВ</h3>
                    <Link className="button" id="button" >9990 тенге</Link>
                </div>
                <div className="Sub-plan">
                    <h2>PLATINUM</h2>
                    <h3>План на 1 месяц</h3>
                    <h3>800 ТОКЕНОВ</h3>
                    <Link className="button" id="button">14990 тенге</Link>
                </div>
                <div className="Sub-plan">
                    <h2>DIAMOND</h2>
                    <h3>План на 1 месяц</h3>
                    <h3>1200 ТОКЕНОВ</h3>
                    <Link className="button" id="button">19990</Link>
                </div>
            </div>
        </div>
    )
}

export default Subscription;
